import { expect, sample, test, uniqueName } from "../../fixtures";
import type { APIRequestContext } from "@playwright/test";

const KINDS = ["w9", "insurance_certificate", "contract"] as const;

type Vendor = { id: string };
type Doc = { id: string; status: string };
type QueueItem = { vendor_id: string; lowest_confidence: number };

async function createSubmittedVendor(member: APIRequestContext, label: string): Promise<string> {
  const created = await member.post("/api/vendors", {
    data: {
      name: uniqueName(label),
      category: "services",
      contact_email: `${uniqueName("contact").replace(/\s+/g, ".")}@example.test`,
    },
  });
  expect(created.status()).toBe(201);
  const vendor = (await created.json()) as Vendor;

  for (const kind of KINDS) {
    const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind,
        file: {
          name: `${kind}.pdf`,
          mimeType: "application/pdf",
          buffer: Buffer.from(`%PDF-1.4 ${uniqueName(kind)}`),
        },
      },
    });
    expect(upload.status()).toBe(201);
    const doc = (await upload.json()) as Doc;

    // Extraction is asynchronous; poll the document until it has been extracted.
    let status = doc.status;
    for (let i = 0; i < 60 && status === "processing"; i++) {
      await new Promise((r) => setTimeout(r, 1000));
      const res = await member.get(`/api/documents/${doc.id}`);
      expect(res.status()).toBe(200);
      status = ((await res.json()) as Doc).status;
    }
    expect(status, `${kind} extraction`).toBe("extracted");
  }

  const submit = await member.post(`/api/vendors/${vendor.id}/submit`);
  expect(submit.status()).toBe(200);
  expect((await submit.json()).status).toBe("in_review");
  return vendor.id;
}

test.describe("review queue ordering", () => {
  test(
    "the review queue lists vendors by lowest confidence, ascending",
    { tag: "@REV-03" },
    async ({ apiAs }) => {
      // Arrange: two vendors in review. Their confidences come from the extraction
      // pipeline on the uploaded documents, so the test relies on the ordering
      // contract rather than hard-coding the 0.40 / 0.95 values.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");
      const first = await createSubmittedVendor(member, "Queue Low");
      const second = await createSubmittedVendor(member, "Queue High");

      // Act
      const response = await reviewer.get("/api/review-queue");

      // Assert
      expect(response.status()).toBe(200);
      const items = (await response.json()) as QueueItem[];

      // The queue is shared with other parallel tests, so check global ordering
      // and the relative position of our two vendors.
      for (let i = 0; i + 1 < items.length; i++) {
        expect(items[i].lowest_confidence).toBeLessThanOrEqual(items[i + 1].lowest_confidence);
      }

      const indexFirst = items.findIndex((item) => item.vendor_id === first);
      const indexSecond = items.findIndex((item) => item.vendor_id === second);
      expect(indexFirst).toBeGreaterThanOrEqual(0);
      expect(indexSecond).toBeGreaterThanOrEqual(0);

      const lowerConfidenceVendor =
        items[indexFirst].lowest_confidence <= items[indexSecond].lowest_confidence ? indexFirst : indexSecond;
      const higherConfidenceVendor = lowerConfidenceVendor === indexFirst ? indexSecond : indexFirst;
      expect(lowerConfidenceVendor).toBeLessThan(higherConfidenceVendor);
    },
  );
});
